layer.css:
[data-ryt="footer"] { color: rgb(73, 80, 87); background-color: rgb(248, 249, 250); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="button"] { color: var(--ryt-bg); background-color: rgb(0, 102, 255); border-top: 1px solid rgb(0, 102, 255); border-right: 1px solid rgb(0, 102, 255); border-bottom: 1px solid rgb(0, 102, 255); border-left: 1px solid rgb(0, 102, 255); border-radius: 5px; font-family: -apple-system, BlinkMacSystemFont, "segoe ui", roboto, "helvetica neue", ubuntu; font-weight: 600; font-style: normal; line-height: 1.5; letter-spacing: 0.5px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 14px; padding-right: 30px; padding-bottom: 14px; padding-left: 30px; transition: 0.3s }
[data-ryt="button"]:hover { color: #ffffff; background-color: #0057d9 }
